  const h = Math.floor(seconds / 3600);
  return `已停止 ${h} 小时`;
}
if (seconds < 86_400 * 7) {
  const d = Math.floor(seconds / 86_400);
  return `已停止 ${d} 天`;
}
if (seconds < 86_400 * 30) {
  const w = Math.floor(seconds / (86_400 * 7));
  return `已停止 ${w} 周`;
}
const mo = Math.floor(seconds / (86_400 * 30));
return `已停止 ${mo} 个月`;

